let wave = 1;

function start() {
  game.vars.wave = wave;
  game.every(20, () => {
    wave++;
    game.vars.wave = wave;
    const spawner = game.find('Enemy Gate');
    const settings = spawner.getComponent('Spawner');
    settings.interval = Math.max(0.5, settings.interval * 0.85);
    game.hud.message('Wave ' + wave + '!', 1.5);
    game.fx.shake(0.2, 0.4);
    audio.sfx('powerup');
  });
}
